    @Test void runCapPlusOneRefusesWholeScopeWithoutPrefixMutation(){UUID target=conversation("rows");flow.tx.executeWithoutResult(t->{flow.lockOwner(owner);for(int i=0;i<1001;i++)db.update("INSERT INTO runs(id,owner_id,conversation_id,status) VALUES (?,?,?,'SUCCEEDED')",UUID.randomUUID(),owner,target);});error(()->deletion.state(session,target),413,"CONVERSATION_DELETION_SCOPE_LIMIT");assertEquals(1001,count("runs"));assertEquals(0,count("conversation_deletion_ledger"));}
    @Test void revokedSessionAndFutureReauthenticationNeverAuthorizeNewDeletion(){UUID target=conversation("auth");var p=prepare(target);db.update("UPDATE sessions SET reauthenticated_at=clock_timestamp()+interval '1 minute' WHERE token_hash=?",session.hash());error(()->commit(p,UUID.randomUUID()),403,"REAUTHENTICATION_REQUIRED");db.update("UPDATE sessions SET revoked_at=clock_timestamp() WHERE token_hash=?",session.hash());error(()->commit(p,UUID.randomUUID()),401,"SESSION_REVOKED");assertNull(db.queryForObject("SELECT deleted_at FROM conversations WHERE id=?",Object.class,target));}
    @Test void graphSnapshotDoesNotIncludeObservationTimeOrLateNumericReceipts(){UUID target=conversation("stable snapshot");answered(target,"unchanged");var first=deletion.state(session,target);var second=deletion.state(session,target);assertEquals(first.get("content_version"),second.get("content_version"));assertEquals(first.get("content_digest"),second.get("content_digest"));}
    @Test void confirmationBooleanHashAndUnknownAuthorityFieldsAreStrict(){UUID target=conversation("strict"),key=UUID.randomUUID();var p=prepare(target);for(Object confirm:List.of(false,"true",1)){var body=new LinkedHashMap<String,Object>();body.put("payload_hash",p.get("payload_hash"));body.put("expected_version",p.get("expected_version"));body.put("expected_digest",p.get("expected_digest"));body.put("confirm",confirm);error(()->deletion.confirm(session,key,(UUID)p.get("id"),json(body)),400,"INVALID_REQUEST");}var body=Json.MAPPER.convertValue(confirmation(p),Map.class);body.put("scope_policy","CONVERSATION_SOURCE_V1");error(()->deletion.confirm(session,key,(UUID)p.get("id"),json(body)),400,"INVALID_REQUEST");assertEquals(0,count("conversation_deletion_ledger"));}

    @Test void concurrentDifferentKeyConfirmsConsumeOneAuthorityOnly() throws Exception {UUID target=conversation("concurrent");answered(target,"closed source");var p=prepare(target);var gate=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){java.util.concurrent.Callable<String> work=()->{gate.await();try{return (String)commit(p,UUID.randomUUID()).get("status");}catch(ApiException e){return e.code;}};var a=pool.submit(work);var b=pool.submit(work);gate.countDown();assertEquals(Set.of("COMMITTED","APPROVAL_CONSUMED"),Set.of(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS)));}assertEquals(1,count("conversation_deletion_mutations"));assertEquals(1,count("conversation_delete_approvals"));}
    @Test void authenticationIsRecheckedAfterWaitingForOwnerLock() throws Exception {UUID target=conversation("lock wait");var p=prepare(target);try(var pool=java.util.concurrent.Executors.newSingleThreadExecutor()){var pending=new ArrayList<java.util.concurrent.Future<ApiException>>();flow.tx.executeWithoutResult(t->{flow.lockOwner(owner);pending.add(pool.submit(()->assertThrows(ApiException.class,()->commit(p,UUID.randomUUID()))));db.update("UPDATE sessions SET reauthenticated_at=clock_timestamp()-interval '301 seconds' WHERE token_hash=?",session.hash());});var failure=pending.getFirst().get(10,java.util.concurrent.TimeUnit.SECONDS);assertEquals("REAUTHENTICATION_REQUIRED",failure.code);}assertEquals(0,count("conversation_deletion_ledger"));assertNull(db.queryForObject("SELECT deleted_at FROM conversations WHERE id=?",Object.class,target));}
    @Test void exactRunCapIsWholeScopeAndNotADeletionPrefix(){UUID target=conversation("at run cap");flow.tx.executeWithoutResult(t->{flow.lockOwner(owner);for(int i=0;i<1000;i++)db.update("INSERT INTO runs(id,owner_id,conversation_id,status) VALUES (?,?,?,'SUCCEEDED')",UUID.randomUUID(),owner,target);});var p=prepare(target);assertEquals(1000L,((Number)((Map<?,?>)p.get("source_counts")).get("runs")).longValue());assertEquals("COMMITTED",commit(p,UUID.randomUUID()).get("status"));assertEquals(1000L,db.queryForObject("SELECT count(*) FROM runs WHERE conversation_id=? AND content_deleted_at IS NOT NULL",Long.class,target));}

